import{_ as a,o as c,c as s,a2 as p}from"./chunks/framework.BXzK3EA4.js";const t="/assets/03ae69ccbf56f711.CmUm38g9.png",o="/assets/5a76eaa1334ad7f4.DESZ6nE4.png",i="/assets/afefc3f8cdbdbf9d.BVN614qf.png",l="/assets/32dec15fea0fb436.DWl_FQKJ.png",u=JSON.parse('{"title":"Linux系统如何查看内存使用情况以及清理缓存","description":"","frontmatter":{"title":"Linux系统如何查看内存使用情况以及清理缓存"},"headers":[],"relativePath":"ops-knowledge-base/operating-system/linux/check-memory-and-clear-cache.md","filePath":"ops-knowledge-base/operating-system/linux/check-memory-and-clear-cache.md","lastUpdated":1788259091000}'),r={name:"ops-knowledge-base/operating-system/linux/check-memory-and-clear-cache.md"};function n(d,e,_,m,h,f){return c(),s("div",null,[...e[0]||(e[0]=[p('<p>有时服务器卡顿，不一定是cpu使用率过高，也有可能是内存不够用了，可以参考下面的方法来查看，并及时清理。</p><p>1.查看服务器物理内存、交换分区使用情况的命令：free -h</p><p><img src="'+t+'" alt=""></p><ul><li><p>totel：机器总的物理内存；</p></li><li><p>used：已使用的内存；</p></li><li><p>free：空闲的物理内存；</p></li><li><p>shared：被共享使用的物理内存；</p></li><li><p>buff/cache：可以理解为缓存；</p></li><li><p>available：还可以被应用程序使用的物理内存；available = free + buffer + cache（这只是理想中的计算方式，实际中的数据往往有较大的误差）。</p></li></ul><p>2.清理缓存命令：</p><p>echo 1 &gt; /proc/sys/vm/drop_caches //释放pagecache页面缓存</p><p><img src="'+o+'" alt=""></p><p>echo 2 &gt; /proc/sys/vm/drop_caches //释放dentries（目录缓存）和inodes缓存</p><p><img src="'+i+'" alt=""></p><p>echo 3 &gt; /proc/sys/vm/drop_caches //释放pagecache,dentries 和 inodes缓存</p><p><img src="'+l+'" alt=""></p><p>注：echo $? #返回执行结果，返回值为0 代表执行成功.</p><ul><li>echo 0 是不释放缓存</li><li>echo 1 是释放pagecache页面缓存（清空最近放问过的文件页面缓存）</li><li>ehco 2 是释放dentries（目录缓存）和inodes缓存（清空目录项缓存和文件节点缓存）</li><li>echo 3 是释放 1 和 2 中说到的所有缓存</li></ul>',13)])])}const b=a(r,[["render",n]]);export{u as __pageData,b as default};
